const listPatients = `-- name: ListPatients :many
SELECT p.id, p.user_id, p.status, p.first_name, p.last_name, p.birth_date, p.sex, p.email, p.phone, p.goal, p.goal_notes, p.clinical_indications, p.measurements_visible, p.quota_override_bytes, p.created_by, p.created_at, p.updated_at, p.deleted_at, p.menarche_age, p.menarche_unknown, count(*) OVER () AS total,
       NOT EXISTS (
         SELECT 1 FROM consent_documents d
         WHERE d.is_active AND NOT EXISTS (
           SELECT 1 FROM consent_acceptances a
           WHERE a.consent_document_id = d.id AND a.patient_id = p.id AND a.revoked_at IS NULL)
       ) AS consent_complete
FROM patients p
WHERE ((p.deleted_at IS NOT NULL) = $1::bool)
  AND ($2::text = '' OR p.status = $2::text)
  AND ($3::text = '' OR p.goal = $3::text)
  AND ($4::text = ''
       OR unaccent(p.first_name || ' ' || p.last_name || ' ' || p.email || ' ' || p.phone) ILIKE '%' || unaccent($4::text) || '%')
ORDER BY lower(p.last_name), lower(p.first_name), p.id
LIMIT $6::int OFFSET $5::int
`

type ListPatientsParams struct {
	OnlyDeleted bool   `json:"only_deleted"`
	Status      string `json:"status"`
	Goal        string `json:"goal"`
	Search      string `json:"search"`
	PageOffset  int32  `json:"page_offset"`
	PageLimit   int32  `json:"page_limit"`
}

type ListPatientsRow struct {
	ID                  uuid.UUID          `json:"id"`
	UserID              uuid.NullUUID      `json:"user_id"`
	Status              string             `json:"status"`
	FirstName           string             `json:"first_name"`
	LastName            string             `json:"last_name"`
	BirthDate           pgtype.Date        `json:"birth_date"`
	Sex                 string             `json:"sex"`
	Email               string             `json:"email"`
	Phone               string             `json:"phone"`
	Goal                string             `json:"goal"`
	GoalNotes           string             `json:"goal_notes"`
	ClinicalIndications string             `json:"clinical_indications"`
	MeasurementsVisible bool               `json:"measurements_visible"`
	QuotaOverrideBytes  pgtype.Int8        `json:"quota_override_bytes"`
	CreatedBy           uuid.UUID          `json:"created_by"`
	CreatedAt           pgtype.Timestamptz `json:"created_at"`
	UpdatedAt           pgtype.Timestamptz `json:"updated_at"`
	DeletedAt           pgtype.Timestamptz `json:"deleted_at"`
	MenarcheAge         pgtype.Int2        `json:"menarche_age"`
	MenarcheUnknown     bool               `json:"menarche_unknown"`
	Total               int64              `json:"total"`
	ConsentComplete     bool               `json:"consent_complete"`
}

// Filtros en el servidor y paginación (§16, §20.2). Búsqueda sin acentos.
func (q *Queries) ListPatients(ctx context.Context, arg ListPatientsParams) ([]ListPatientsRow, error) {
	rows, err := q.db.Query(ctx, listPatients,
		arg.OnlyDeleted,
		arg.Status,
		arg.Goal,
		arg.Search,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListPatientsRow
	for rows.Next() {
		var i ListPatientsRow
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.Status,
			&i.FirstName,
			&i.LastName,
			&i.BirthDate,
			&i.Sex,
			&i.Email,
			&i.Phone,
			&i.Goal,
			&i.GoalNotes,
			&i.ClinicalIndications,
			&i.MeasurementsVisible,
			&i.QuotaOverrideBytes,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.MenarcheAge,
			&i.MenarcheUnknown,
			&i.Total,
			&i.ConsentComplete,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

